package presentation.snippets.lesson4.slide272

import presentation.support.*

interface Clickable {
  fun click() = println("clicked")
}

interface Focusable {
  fun click() = println("focused")
}

class Button : Clickable, Focusable {
  override fun click() {
    super<Clickable>.click()
    super<Focusable>.click()
  }
}
